Let Assumptions A:1, A:3, A:4 and A:5 hold. Then there is a functor 

	\[ \iota(\mathcal{X}) \xrightarrow{\mathrm{Dyn}} \text{LeftSlice} \left(  \mathcal{X}  \right) , \]

	which maps every object $\Omega\in \mathcal{X}$ to the left slice $\left[ \mathcal{X} \;;\; \Omega \right]$. It maps an arrow $\iota \Omega \xrightarrow{F} \iota \Omega'$ into a functor $$\left[ \mathcal{X} \;;\; \Omega \right] \xrightarrow{\tau_F} \left[ \mathcal{X} \;;\; \Omega' \right]$$ such that for every $A \xrightarrow{a} \Omega \in \left[ \mathcal{X} \;;\; \Omega \right]$, $\tau_F(a)$ creates a commutation square

	\begin{equation} 
		\begin{tikzcd}
			\iota A \arrow[d, "\iota a"']  \\
			\iota \Omega \arrow[r, "F"'] & \iota \Omega'               
		\end{tikzcd} \quad \Rightarrow \quad 
		\begin{tikzcd}
			\iota A \arrow[d, "\iota a"'] \arrow[r, "\tau_F(a)", Shobuj] & \iota B \arrow[d, "\iota b", Shobuj] \\
			\iota \Omega \arrow[r, "F"'] & \iota \Omega'               
		\end{tikzcd}
	\end{equation}

	for some  $B \xrightarrow{b} \Omega \in \left[ \mathcal{X} \;;\; \Omega' \right]$. Moreover, this square is universal in the sense that for any slice-object $b':B'\to \Omega'$ and any morphism $f:\iota A \to \iota B'$, if the blue commutation square shown below holds 

	\begin{equation} 
		\forall \begin{tikzcd} 	\end{tikzcd}
		\begin{tikzcd}
			& & \iota B' \arrow[ldd, "\iota b'", bend left=49, Akashi] \\
			\iota A \arrow[d, "\iota a"', Akashi] \arrow[r, "\tau_F(a)", Shobuj] \arrow[rru, "f", bend left, Akashi] & \iota B \arrow[d, "\iota b", Shobuj] \arrow[ur, "\exists!\phi"', Holud] & \\
			\iota \Omega \arrow[r, "F"', Akashi] & \iota \Omega' & 
		\end{tikzcd} ,
	\end{equation}

	then there is a unique morphism $\phi$ which factors the outer commutation loop into the inner commutation loop.

Assume the arrangement of (1), and let Assumption A:2 hold. Fix an object $\alpha a \xrightarrow{F} \beta b$ of the comma category $\left[ \alpha \;;\; \beta \right]$. Then there is a functor $\tau_{F} : \left[ \mathcal{A} \;;\; a \right] \to \left[ \alpha \;;\; \beta \right]$ such that for any object $a'\xrightarrow{f} a$ in $\left[ \mathcal{A} \;;\; a \right]$, there is an object $b'\xrightarrow{g} b$ in $\left[ \mathcal{B} \;;\; b \right]$, such that the following commutation holds 

	\begin{equation} 
		\begin{tikzcd} a' \arrow[d, "f"'] \\ b \end{tikzcd}
		\quad \Rightarrow \quad
		\begin{tikzcd}
			\alpha a' \arrow[d, "\alpha f"'] \arrow[r, "\tau_{F}(f)"] & \beta b' \arrow[d, "\beta g"] \\
			\alpha a \arrow[r, "F"'] & \beta b 
		\end{tikzcd}
	\end{equation}

	Moreover, $\tau_{F}(f)$ is minimal in the sense for any other object $b'' \xrightarrow{g} b$, if the commutation shown below on the left holds :

	\[
	\begin{tikzcd}
		\alpha a' \arrow[d, "\alpha f"'] \arrow[r, "\tilde{F}"] & \beta b'' \arrow[d, "\beta g''"] \\
		\alpha a \arrow[r, "F"'] & \beta b 
	\end{tikzcd} \quad \Rightarrow \quad 
	\begin{tikzcd}
		& & \beta b' \arrow[ldd, "\beta g'", bend left=50] \arrow[ld, "\beta \phi", dotted] \\
		\alpha a' \arrow[d, "\alpha f"'] \arrow[r, "\tilde{F}"'] \arrow[rru, "\tau_{F}(f)", bend left] & \beta b'' \arrow[d, "\beta g''"] & \\
		\alpha a \arrow[r, "F"'] & \beta b & 
	\end{tikzcd}
	\]

	then there is a unique morphism $b' \xrightarrow{\phi} b''$ such that the commutation on the right holds.

Under the same assumptions as Theorem~thm:1  and the category in  (2). Then there is a functor

	\[ \bar{\tau}_F : \left[ \mathcal{A} \;;\; a \right] \to \left[  \mathrm{Frgt}_2^{ \left[ \alpha \;;\; \beta \right] }  \;;\;  b  \right] \]

	such that the functors $\tau_{F}$ and $\mathrm{Dyn}_{F}$ are created via composition :

	\begin{equation}  
		\begin{tikzcd}
			&& \left[ \mathcal{A} \;;\; a \right] \arrow[dll, "\tau_F"', dashed] \arrow[rr, "\mathrm{Dyn}_F", dashed] \arrow[drr, "\bar{\tau}_F"] && \left[ \mathcal{B} \;;\; b \right] \\
			\left[ \alpha \;;\; \beta \right] && \mathcal{UR} \left( \alpha ,\, \beta \right) \arrow[ll, "\mathrm{Frgt}_1"] && \left[  \mathrm{Frgt}_2^{ \left[ \alpha \;;\; \beta \right] }  \;;\; b \right] \arrow[ll, "\subseteq"] \arrow[u, "\text{Restrict}"']
		\end{tikzcd}
	\end{equation}

\begin{equation}  
		\begin{tikzcd}
			&& \left[ \mathcal{A} \;;\; a \right] \arrow[dll, "\tau_F"', dashed] \arrow[rr, "\mathrm{Dyn}_F", dashed] \arrow[drr, "\bar{\tau}_F"] && \left[ \mathcal{B} \;;\; b \right] \\
			\left[ \alpha \;;\; \beta \right] && \mathcal{UR} \left( \alpha ,\, \beta \right) \arrow[ll, "\mathrm{Frgt}_1"] && \left[  \mathrm{Frgt}_2^{ \left[ \alpha \;;\; \beta \right] }  \;;\; b \right] \arrow[ll, "\subseteq"] \arrow[u, "\text{Restrict}"']
		\end{tikzcd}
	\end{equation}

\begin{equation} 
	\begin{tikzcd} [row sep = large]
		\text{Arrow} \left[  \left[ \alpha \;;\; \beta \right]  \right] \arrow[dd, "DL"'] \arrow[rr, "UR", Shobuj] \arrow[bend left = 30, Holud, "\mathrm{Frgt}_1", rrrr] && \mathcal{UR} \left( \alpha ,\, \beta \right) \arrow[drrrr, "\mathrm{Frgt}_2"'] \arrow[rr, "\mathrm{Frgt}_1"] && \left[ \alpha \;;\; \beta \right] \arrow[drr, "\mathrm{Frgt}_2"] \\
		&& && && \mathcal{B} \\
		\mathcal{DL} \left( \alpha ,\, \beta \right) \arrow[rrrr, bend right=20, Holud, dotted, "\gamma_F"'] \arrow[ddrr, "\mathrm{Frgt}_2"', bend right=20] \arrow[rr, "\bar{\gamma}_F"', Shobuj, dotted] && \mathcal{UR} \left( \alpha ,\, \beta \right) \arrow[rr, "\mathrm{Frgt}_1"] \arrow[urrrr, "\mathrm{Frgt}_2"] && \left[ \alpha \;;\; \beta \right] \arrow[urr, "\mathrm{Frgt}_2"'] \\ \\
		&& \left[ \alpha \;;\; \beta \right] \arrow[uuurrrr, "\mathrm{Frgt}_2"', bend right=20] & \left[ \mathrm{Frgt}_2^{ \left[ \alpha \;;\; \beta \right]} \;;\; b \right] \arrow[dr, Akashi, "\text{Restrict}"] \arrow[luu, Akashi, "\subseteq"] \\
		\left[ \mathcal{A} \;;\; a \right] \arrow[Akashi, rrru, bend right=40, "\bar{\tau}_F"'] \arrow[rrrr, bend right=30, Shobuj, "\mathrm{Dyn}_F"'] \arrow[Itranga]{uuu}{ \Phi_{F} } \arrow[rr] && \star \arrow[u, Itranga, "F"] \arrow[uuuurrrr, Itranga, "b"', bend right=30] && \left[ \mathcal{B} \;;\; b \right] \arrow[uuuurr, "\mathrm{Frgt}_2"', bend right=30]
	\end{tikzcd}
\end{equation}

\begin{equation} 
	\begin{tikzcd}
		\mathcal{P} \arrow[r, "\mathcal{T}"] \arrow[d, ""] & \mathcal{UR} \left( \alpha ,\, \beta \right) \arrow[d, "\mathrm{Frgt}_2"] \\
		\star \arrow[r, "b"'] & \mathcal{B}
	\end{tikzcd} \quad \Rightarrow \quad 
	\begin{tikzcd}
		\mathcal{P} \arrow[drr, "\mathcal{T}", bend left=20] \arrow[ddr, "", bend right=20] \arrow[Akashi, dr, "\mathcal{T}'"] \arrow[Akashi, dd, "\mathcal{T}''"', dashed]  \\
		& \left[ \mathrm{Frgt}_2^{ \left[ \alpha \;;\; \beta \right]} \;;\; b \right] \arrow[dl, Holud, "\text{Restrict}"] \arrow[r, "\subset"] \arrow[d, ""] & \mathcal{UR} \left( \alpha ,\, \beta \right) \arrow[d, "\mathrm{Frgt}_2"] \\
		\left[ \mathcal{B} \;;\; b \right] & \star \arrow[r, "b"'] & \mathcal{B}
	\end{tikzcd}
\end{equation}
